Γöé 0       Γöé "CREATE OR REPLACE FUNCTION public.qms_patient_create_booking(p_cccd text, p_ho_ten text, p_ngay_sinh date, p_gioi_tinh text, p_dan_toc text, p_ma_tinh integer, p_ma_quan_huyen integer, p_ma_phuong_xa integer, p_dia_chi_chi_tiet text, p_so_dien_thoai text, p_ma_khoa text, p_ma_phong_kham integer, p_ngay_hen date, p_gio_hen text, p_ly_do_kham text, p_occupation integer, p_doctor text, p_email text DEFAULT ''::text, p_type text DEFAULT 'ONL'::text, p_ngay_cap_cccd date DEFAULT NULL::date)\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\n  DECLARE\n    v_res      INTEGER;\n    v_idx      INTEGER;\n    v_receptno INTEGER;\n    v_count    INTEGER;\n  BEGIN\n    -- Kiß╗âm tra xem block giß╗¥ hß║╣n ─æ├ú ─æ╞░ß╗úc ─æ─âng k├╜ ch╞░a\n    SELECT COUNT(*)\n    INTO v_count\n    FROM hms_schedule_exam\n    WHERE hse_date = p_ngay_hen\n    AND hse_deptid = p_ma_khoa\n    AND hse_roomid = p_ma_phong_kham\n    AND hse_time   = p_gio_hen\n    AND hse_status = 'S';\n    IF v_count     > 0 THEN\n      RAISE NOTICE 'Block giß╗¥ hß║╣n ─æ├ú ─æ╞░ß╗úc ─æ─âng k├╜';\n      RETURN -1;\n    END IF;\n    -- Kiß╗âm tra xem bß╗çnh nh├ón ─æ├ú ─æ─âng k├╜ trong ng├áy ch╞░a\n    SELECT COUNT(*)\n    INTO v_count\n    FROM qms_patient\n    WHERE qms_contact        = p_so_dien_thoai\n    AND qms_deptid           = p_ma_khoa\n    AND qms_appointment_date = p_ngay_hen\n    AND qms_patientname      = p_ho_ten\n    AND qms_birthdate        = p_ngay_sinh\n    AND qms_sex              = p_gioi_tinh;\n    IF v_count               > 0 THEN\n      RAISE NOTICE 'Chß╗ë ─æ╞░ß╗úc ─æ─âng k├╜ 1 lß║ºn trong ng├áy';\n      RETURN -3;\n    END IF;\n    -- Lß║Ñy hse_receptno, nß║┐u kh├┤ng c├│ th├¼ ─æß║╖t v_receptno = 0\n    SELECT hse_receptno\n    INTO v_receptno\n    FROM hms_schedule_exam\n    WHERE hse_deptid   = p_ma_khoa\n    AND hse_roomid     = p_ma_phong_kham\n    AND hse_date::DATE = p_ngay_hen::DATE\n    AND hse_time       = p_gio_hen;\n    IF NOT FOUND THEN\n      v_receptno := 0;\n    END IF;\n    IF v_receptno IS NULL OR v_receptno <= 0 THEN\n      RAISE NOTICE 'Block ch╞░a ─æ╞░ß╗úc tß║ío';\n      RETURN -2;\n    END IF;\n    -- Lß║Ñy gi├í trß╗ï tiß║┐p theo cß╗ºa sequence\n    SELECT nextval('qms_idx_asq')\n    INTO v_idx;\n    -- Th├¬m bß║ún ghi v├áo qms_patient\n    INSERT\n    INTO qms_patient\n      (\n        qms_idx,\n        qms_idcard,\n        qms_idcard_issuedate, -- NEW\n        qms_patientname,\n        qms_birthdate,\n        qms_sex,\n        qms_ethnic,\n        qms_prov_id,\n        qms_dist_id,\n        qms_vill_id,\n        qms_address,\n        qms_contact,\n        qms_email,\n        qms_deptid,\n        qms_roomid,\n        qms_appointment_date,\n        qms_appointment_time,\n        qms_reason,\n        qms_status,\n        qms_receptno,\n        qms_occupation,\n        qms_doctor,\n        qms_type\n      )\n      VALUES\n      (\n        v_idx,\n        p_cccd,\n        p_ngay_cap_cccd, -- NEW\n        p_ho_ten,\n        p_ngay_sinh,\n        p_gioi_tinh,\n        p_dan_toc,\n        p_ma_tinh,\n        p_ma_quan_huyen,\n        p_ma_phuong_xa,\n        p_dia_chi_chi_tiet,\n        p_so_dien_thoai,\n        p_email,\n        p_ma_khoa,\n        p_ma_phong_kham,\n        p_ngay_hen,\n        p_gio_hen,\n        p_ly_do_kham,\n        'O',\n        v_receptno,\n        p_occupation,\n        p_doctor,\n        p_type\n      );\n    -- Lß║Ñy sß╗æ d├▓ng ß║únh h╞░ß╗ƒng\n    GET DIAGNOSTICS v_res = ROW_COUNT;\n    RAISE NOTICE 'Sß╗æ bß║ún ghi ─æ╞░ß╗úc ch├¿n: %',\n    v_res;\n    RETURN v_idx;\n  END;\n  $function$\n"                                                                                                                                                                                                                                                                                                                                                               Γöé
Γöé 1       Γöé "CREATE OR REPLACE FUNCTION public.qms_patient_create_booking(p_cccd text, p_ho_ten text, p_ngay_sinh date, p_gioi_tinh text, p_dan_toc text, p_ma_tinh integer, p_ma_quan_huyen integer, p_ma_phuong_xa integer, p_dia_chi_chi_tiet text, p_so_dien_thoai text, p_ma_khoa text, p_ma_phong_kham integer, p_ngay_hen date, p_gio_hen text, p_ly_do_kham text, p_occupation integer, p_doctor text, p_email text DEFAULT ''::text, p_type text DEFAULT 'ONL'::text, p_ngay_cap_cccd date DEFAULT NULL::date, p_is_priority boolean DEFAULT false, p_is_insurance boolean DEFAULT false, p_ma_chuyen_khoa text DEFAULT ''::text)\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\n  DECLARE\n    v_res      INTEGER;\n    v_idx      INTEGER;\n    v_receptno INTEGER;\n    v_count    INTEGER;\n  BEGIN\n    -- Kiß╗âm tra xem block giß╗¥ hß║╣n ─æ├ú ─æ╞░ß╗úc ─æ─âng k├╜ ch╞░a\n    SELECT COUNT(*)\n    INTO v_count\n    FROM hms_schedule_exam\n    WHERE hse_date = p_ngay_hen\n    AND hse_deptid = p_ma_khoa\n    AND hse_roomid = p_ma_phong_kham\n    AND hse_time   = p_gio_hen\n    AND hse_status = 'S';\n    IF v_count     > 0 THEN\n      RAISE NOTICE 'Block giß╗¥ hß║╣n ─æ├ú ─æ╞░ß╗úc ─æ─âng k├╜';\n      RETURN -1;\n    END IF;\n    -- Kiß╗âm tra xem bß╗çnh nh├ón ─æ├ú ─æ─âng k├╜ chuy├¬n khoa n├áy trong ng├áy ch╞░a\n    SELECT COUNT(*)\n    INTO v_count\n    FROM qms_patient\n    WHERE qms_contact        = p_so_dien_thoai\n    AND qms_specialty_code   = p_ma_chuyen_khoa\n    AND qms_appointment_date = p_ngay_hen\n    AND qms_patientname      = p_ho_ten\n    AND qms_birthdate        = p_ngay_sinh\n    AND qms_sex              = p_gioi_tinh\n    AND qms_status           != 'C';\n    IF v_count               > 0 THEN\n      RAISE NOTICE 'Bß╗çnh nh├ón ─æ├ú c├│ lß╗ïch hß║╣n cho chuy├¬n khoa n├áy trong ng├áy';\n      RETURN -3;\n    END IF;\n    -- Lß║Ñy hse_receptno, nß║┐u kh├┤ng c├│ th├¼ ─æß║╖t v_receptno = 0\n    SELECT hse_receptno\n    INTO v_receptno\n    FROM hms_schedule_exam\n    WHERE hse_deptid   = p_ma_khoa\n    AND hse_roomid     = p_ma_phong_kham\n    AND hse_date::DATE = p_ngay_hen::DATE\n    AND hse_time       = p_gio_hen;\n    IF NOT FOUND THEN\n      v_receptno := 0;\n    END IF;\n    IF v_receptno IS NULL OR v_receptno <= 0 THEN\n      RAISE NOTICE 'Block ch╞░a ─æ╞░ß╗úc tß║ío';\n      RETURN -2;\n    END IF;\n    -- Lß║Ñy gi├í trß╗ï tiß║┐p theo cß╗ºa sequence\n    SELECT nextval('qms_idx_asq')\n    INTO v_idx;\n    -- Th├¬m bß║ún ghi v├áo qms_patient\n    INSERT\n    INTO qms_patient\n      (\n        qms_idx,\n        qms_idcard,\n        qms_idcard_issuedate,\n        qms_patientname,\n        qms_birthdate,\n        qms_sex,\n        qms_ethnic,\n        qms_prov_id,\n        qms_dist_id,\n        qms_vill_id,\n        qms_address,\n        qms_contact,\n        qms_email,\n        qms_deptid,\n        qms_roomid,\n        qms_appointment_date,\n        qms_appointment_time,\n        qms_reason,\n        qms_status,\n        qms_receptno,\n        qms_occupation,\n        qms_doctor,\n        qms_type,\n        qms_is_priority,\n        qms_is_insurance,\n        qms_specialty_code\n      )\n      VALUES\n      (\n        v_idx,\n        p_cccd,\n        p_ngay_cap_cccd,\n        p_ho_ten,\n        p_ngay_sinh,\n        p_gioi_tinh,\n        p_dan_toc::INTEGER,\n        p_ma_tinh,\n        p_ma_quan_huyen,\n        p_ma_phuong_xa,\n        p_dia_chi_chi_tiet,\n        p_so_dien_thoai,\n        p_email,\n        p_ma_khoa,\n        p_ma_phong_kham,\n        p_ngay_hen,\n        p_gio_hen,\n        p_ly_do_kham,\n        'O',\n        v_receptno,\n        p_occupation,\n        p_doctor,\n        p_type,\n        p_is_priority,\n        p_is_insurance,\n        p_ma_chuyen_khoa\n      );\n    -- Lß║Ñy sß╗æ d├▓ng ß║únh h╞░ß╗ƒng\n    GET DIAGNOSTICS v_res = ROW_COUNT;\n    RAISE NOTICE 'Sß╗æ bß║ún ghi ─æ╞░ß╗úc ch├¿n: %',\n    v_res;\n    RETURN v_idx;\n  END;\n  $function$\n" Γöé
